<template><view class="page"><MobileHeader title="权限设置" back-icon-name="chevron-left"/><view v-for="group in groups" :key="group.title" class="permission-group"><text class="group-title">{{group.title}}</text><ReadinessCard v-for="item in items.filter(i=>group.ids.includes(i.id))" :key="item.id" :title="item.label" :state="item.status==='已允许'||item.status==='已开启'?'ready':isNative?'action':'unknown'" :status="isNative?item.status:'App 内可用'" :action="isNative?'去设置':undefined" :description="descriptions[item.id]" @action="act(item.id)"/></view><text v-if="error" class="error" role="alert">{{error}}</text></view></template>
<script setup lang="ts">
import {ref} from 'vue';import ReadinessCard from '@/components/ReadinessCard.vue';
const isNative=typeof plus!=='undefined';
const groups=[{title:'基础权限',ids:['microphone','camera','files','notifications']},{title:'拨号与通话',ids:['phone','phoneState','callLog','recording']},{title:'高级权限',ids:['overlay','accessibility']},{title:'运行与更新',ids:['battery','install']}];import {onShow} from '@dcloudio/uni-app';import MobileHeader from '@/components/MobileHeader.vue';
import {permissionGranted,requestRuntimePermissions,openSystemSettings,batteryUnrestricted} from '@/modules/device-readiness';
import {bridge,allFilesGranted,specialPermission,sdkVersion} from '@/modules/device-readiness/android';import {openOverlaySettings,mobilePet,refreshMobilePet} from '@/modules/mobile-pet';
const descriptions:Record<string,string>={microphone:'用于语音对话和宠物语音。',files:'用于访问手机中的录音文件；普通聊天不需要开启。',recording:'通话自动录音由手机拨号器提供，请在电话应用设置中手动开启。当前版本不检测录音开关。',overlay:'让手机宠显示在其他应用上方。',accessibility:'当前安装包尚未集成无障碍服务，开启手机的其他服务不会授权本应用。',battery:'减少系统对后台语音的限制；自启动仍需按手机系统单独设置。',install:'用于安装下载完成的 App 更新。'};
const items=ref<any[]>([]),error=ref('');const state=(v:boolean|null)=>v===null?'请在 Android App 中检查':v?'已允许':'未允许';
function accessibility(){const a=bridge();if(!a)return '请在 Android App 中检查';try{const context=a.runtimeMainActivity(),manager=a.invoke(context,'getSystemService','accessibility');const installed=a.invoke(manager,'getInstalledAccessibilityServiceList'),enabled=a.invoke(manager,'getEnabledAccessibilityServiceList',-1);const pkg=a.invoke(context,'getPackageName');let own=0,on=0;for(const [list,isEnabled] of [[installed,false],[enabled,true]]){for(let i=0;i<a.invoke(list,'size');i++){const info=a.invoke(a.invoke(list,'get',i),'getResolveInfo');const service=a.getAttribute(info,'serviceInfo');if(a.getAttribute(service,'packageName')===pkg){if(isEnabled)on++;else own++;}}}return !own?'当前包未集成无障碍服务':on?'已开启':'未开启';}catch{return '状态未知，请在系统设置中核对';}}
const runtimePermissions:Record<string,string>={microphone:'RECORD_AUDIO',camera:'CAMERA',phone:'CALL_PHONE',phoneState:'READ_PHONE_STATE',callLog:'READ_CALL_LOG'};
function notificationStatus(){const sdk=sdkVersion();if(!sdk)return null;if(sdk>=33)return permissionGranted('android.permission.POST_NOTIFICATIONS');return specialPermission('通知',a=>a.invoke(a.invoke(a.runtimeMainActivity(),'getSystemService','notification'),'areNotificationsEnabled'));}
function installStatus(){const sdk=sdkVersion();if(!sdk)return null;if(sdk<26)return true;return specialPermission('安装未知应用',a=>a.invoke(a.invoke(a.runtimeMainActivity(),'getPackageManager'),'canRequestPackageInstalls'));}
async function refresh(){await refreshMobilePet();items.value=[...Object.entries(runtimePermissions).map(([id,permission])=>({id,label:({microphone:'麦克风',camera:'相机',phone:'拨打电话',phoneState:'电话状态',callLog:'通话记录'})[id],status:state(permissionGranted('android.permission.'+permission))})),{id:'recording',label:'通话自动录音',status:'手动设置'},{id:'files',label:'文件访问',status:state(allFilesGranted())},{id:'overlay',label:'悬浮窗',status:state(mobilePet.permission)},{id:'notifications',label:'通知权限',status:state(notificationStatus())},{id:'battery',label:'电池优化',status:state(batteryUnrestricted())},{id:'install',label:'安装未知应用',status:state(installStatus())},{id:'accessibility',label:'无障碍权限',status:accessibility()}];}
async function act(id:string){error.value='';try{if(id==='recording'){uni.showModal({title:'通话自动录音',content:'请打开手机自带的电话应用，在设置中查找“通话录音”或“自动录音”。不同机型入口不同，部分机型不支持。',showCancel:false});return;}if(runtimePermissions[id])await requestRuntimePermissions(['android.permission.'+runtimePermissions[id]]);else if(id==='overlay')await openOverlaySettings();else if(id==='notifications'&&sdkVersion()>=33)await requestRuntimePermissions(['android.permission.POST_NOTIFICATIONS']);else openSystemSettings(id==='files'?'files':id==='install'?'install':id==='notifications'?'notifications':id==='accessibility'?'accessibility':'battery');await refresh();}catch{error.value='无法完成设置，请在手机系统设置中手动开启';}}

onShow(()=>{void refresh();});
</script><style scoped>.page{box-sizing:border-box;max-width:500px;min-height:100vh;margin:auto;background:#f5f6fa;padding:12px 20px calc(32px + env(safe-area-inset-bottom))}.permission-group{margin-top:28px}.group-title{display:block;font-size:13px;font-weight:500;color:#8b94a5;letter-spacing:1px;margin:0 0 12px 4px}.error{display:block;color:#b44343;margin-top:15px}</style>